vulnerable_code:
app.put('/api/profile/update', async (req, res) => {
  await Profile.update(req.body, { where: { id: req.body.itemId } });
  res.send('Updated');
});

corrected_code:
app.put('/api/profile/update', async (req, res) => {
  await Profile.update(req.body, { where: { id: req.body.itemId, ownerId: req.user.id } });
  res.send('Updated');
});
